var ttytable = require('tty-table');

function exchangeStatusWord(result) {
    if (result.status === 0) return 'OK';
    if (result.status === 1) return 'WARN';
    if (result.status === 2) return 'FAIL';
    return 'UNKNOWN';
}

function commaSafe(str) {
    if (!str) return '';
    return str.replace(/,/g, ' ');
}

