                            data: {TagSet: [{Key: 'team', Value: 'data'}]}
                        }
                    }
                }
            }
        };

        var index;

        before(function() {
            index = tagIndex.build(cache);
        });

        it('indexes EC2 resources by ARN and bare id', function() {
